part tick
  restart never
  sound init
  range B5..B8
  length 1/64
  osc1.level = 0
  noise = 1
  cutoff = 0.95
  resonance = 0.3
  attack = 0
  sustain = 0
  release = 0.03
  insert = filter type hp12, cutoff 3000Hz
  send.spark = 0.55
  send.spark.pre = 1
  send.aurora = 0.45
  send.aurora.pre = 1
  send.tailL = 0.4
  send.tailL.pre = 1
  send.tailR = 0.3
  send.tailR.pre = 1
  send.ratchet = 0.45
